SELECT MIN(impression_date_utc) AS source_observed_on, campaign_id_string, campaign, advertiser_id, advertiser, campaign_country, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM dsp_impressions GROUP BY campaign_id_string, campaign, advertiser_id, advertiser, campaign_country
